-- period_close_run: Execution of an EOD / EOM / EOY close with its checklist steps
CREATE TABLE period_close_run (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  accounting_period_id         uuid NOT NULL REFERENCES accounting_period(id),
  status                       varchar(40) NOT NULL DEFAULT 'QUEUED' CHECK (status IN ('QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED', 'CANCELLED', 'PARTIALLY_SUCCEEDED')),
  started_at                   timestamptz,
  finished_at                  timestamptz,
  steps                        jsonb,
  error                        text,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
COMMENT ON TABLE period_close_run IS 'Execution of an EOD / EOM / EOY close with its checklist steps';
COMMENT ON COLUMN period_close_run.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN period_close_run.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN period_close_run.created_at IS 'Creation time';
COMMENT ON COLUMN period_close_run.created_by IS 'Principal that created the row';
COMMENT ON COLUMN period_close_run.updated_at IS 'Last update time';
COMMENT ON COLUMN period_close_run.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN period_close_run.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN period_close_run.accounting_period_id IS 'Period being closed';
COMMENT ON COLUMN period_close_run.status IS 'Run status';
COMMENT ON COLUMN period_close_run.started_at IS 'Start time';
COMMENT ON COLUMN period_close_run.finished_at IS 'End time';
COMMENT ON COLUMN period_close_run.steps IS 'Checklist: accruals, revaluation, provisions, recon checks, trial balance';
COMMENT ON COLUMN period_close_run.error IS 'Error details';
COMMENT ON COLUMN period_close_run.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN period_close_run.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN period_close_run.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN period_close_run.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN period_close_run.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_period_close_run_tenant ON period_close_run (tenant_id, created_at);
CREATE INDEX ix_period_close_run_accounting_period_id ON period_close_run (accounting_period_id);
ALTER TABLE period_close_run ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON period_close_run USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_period_close_run_touch BEFORE UPDATE ON period_close_run FOR EACH ROW EXECUTE FUNCTION touch_row();

-- ecl_provision: IFRS 9 expected credit loss provision per exposure and reporting date
CREATE TABLE ecl_provision (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  legal_entity_id              uuid NOT NULL,
  reporting_date               date NOT NULL,
  exposure_type                varchar(32) NOT NULL,
  exposure_id                  uuid NOT NULL,
  stage                        varchar(40) NOT NULL CHECK (stage IN ('STAGE_1', 'STAGE_2', 'STAGE_3', 'POCI')),
  ead                          numeric(28,8) NOT NULL,
  pd                           numeric(18,10) NOT NULL,
  lgd                          numeric(18,10) NOT NULL,
  ecl_amount                   numeric(28,8) NOT NULL,
  currency                     char(3) NOT NULL,
  model_version                varchar(32) NOT NULL,
  gl_journal_id                uuid REFERENCES gl_journal(id),
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500),
  CONSTRAINT uq_ecl_provision_1 UNIQUE (tenant_id, exposure_id, reporting_date)
);
COMMENT ON TABLE ecl_provision IS 'IFRS 9 expected credit loss provision per exposure and reporting date';
COMMENT ON COLUMN ecl_provision.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN ecl_provision.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN ecl_provision.created_at IS 'Creation time';
COMMENT ON COLUMN ecl_provision.created_by IS 'Principal that created the row';
COMMENT ON COLUMN ecl_provision.legal_entity_id IS 'Legal entity';
COMMENT ON COLUMN ecl_provision.reporting_date IS 'Reporting date';
COMMENT ON COLUMN ecl_provision.exposure_type IS 'LOAN, CREDIT_LINE, CARD, OVERDRAFT';
COMMENT ON COLUMN ecl_provision.exposure_id IS 'Loan / account id';
COMMENT ON COLUMN ecl_provision.stage IS 'IFRS 9 stage';
COMMENT ON COLUMN ecl_provision.ead IS 'Exposure at default';
COMMENT ON COLUMN ecl_provision.pd IS 'Probability of default (12-month or lifetime)';
COMMENT ON COLUMN ecl_provision.lgd IS 'Loss given default';
COMMENT ON COLUMN ecl_provision.ecl_amount IS 'Expected credit loss';
COMMENT ON COLUMN ecl_provision.currency IS 'Currency';
COMMENT ON COLUMN ecl_provision.model_version IS 'Model version used';
COMMENT ON COLUMN ecl_provision.gl_journal_id IS 'Provision posting';
COMMENT ON COLUMN ecl_provision.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN ecl_provision.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN ecl_provision.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN ecl_provision.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN ecl_provision.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_ecl_provision_tenant ON ecl_provision (tenant_id, created_at);
CREATE INDEX ix_ecl_provision_legal_entity_id ON ecl_provision (legal_entity_id);
CREATE INDEX ix_ecl_provision_exposure_id ON ecl_provision (exposure_id);
CREATE INDEX ix_ecl_provision_gl_journal_id ON ecl_provision (gl_journal_id);
ALTER TABLE ecl_provision ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON ecl_provision USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_ecl_provision_append_only BEFORE UPDATE OR DELETE ON ecl_provision FOR EACH ROW EXECUTE FUNCTION forbid_mutation();

-- erp_export: GL export batch sent to an external ERP (SAP, Oracle, NetSuite)
CREATE TABLE erp_export (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
