COMMENT ON COLUMN erp_export.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN erp_export.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN erp_export.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN erp_export.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_erp_export_tenant ON erp_export (tenant_id, created_at);
